interface FieldDescriptor<Value = unknown> {
  initializer?: (this: object) => Value;
  get?: (this: object) => Value;
  set?: (this: object, value: Value) => void;
  value?: Value;
  writable?: boolean;
  enumerable?: boolean;
  configurable?: boolean;
  isTracked?: boolean;
