  if (badge.id != null) {
    return updateOne(
      "badge",
      badge.id,
      `/admin/badges/${encodeURIComponent(badge.id)}`,
      data,
      normalizeBadgeRecordPayload
    );
  }
  return createOne(`/admin/badges`, data, normalizeBadgeRecordPayload);
