/** The saved composer state of a draft (`DraftsController#index` sends it as a JSON string). */
export interface UserDraftData {
  /** Null or absent when the composer was cleared or the draft was saved without one. */
  reply?: string | null;
  action?: string;
  title?: string | null;
  categoryId?: number | null;
  postId?: number;
  [key: string]: unknown;
}

/**
 * Data a `UserDraft` holds: the `DraftSerializer` payload plus the fields the
 * drafts stream derives from it before calling `create`.
 */
export interface UserDraftFields {
  created_at: string;
  draft_key: string;
  sequence: number;
  /** The drafter. */
  draft_username: string;
  avatar_template: string;
  /** Parsed from the server's JSON string before the draft is created. */
  data: UserDraftData;
  /** Set for drafts on an existing topic. */
  topic_id: number | null;
  /** The author of the replied-to post or topic, else the drafter. */
  username: string;
  username_lower: string;
  /** Present when names are enabled. */
  name?: string | null;
  user_id: number;
  /**
   * The topic's title. New topic and message drafts use the draft's own
   * title instead, which may be missing.
   */
  title?: string | null;
  /** Present when the topic has a title. */
  slug?: string;
  /** Present when the topic has a category. */
  category_id?: number;
  /** Present only when the topic is closed. */
  closed?: true;
  archetype: string | null;
  /** Present only when the topic is archived. */
  archived?: true;
  /** Derived from the draft's reply before the draft is created. */
  excerpt: string;
  /** Present only when the server's excerpt was cut. */
  truncated?: true;
  post_number: number | null;
  /** Set when the draft's composer state names a category. */
  category?: Category | null;
}

// `create()` assigns the server fields at runtime, so the class declares none of
// them. Merging an interface of the same name adds them to the class type, and
// lets plugins add theirs by augmenting `UserDraftFields`.
// eslint-disable-next-line @typescript-eslint/no-empty-object-type, @typescript-eslint/no-unsafe-declaration-merging
export default interface UserDraft extends UserDraftFields {}

// eslint-disable-next-line @typescript-eslint/no-unsafe-declaration-merging
export default class UserDraft extends RestModel {
  @service declare currentUser: User | null;

  get titleHtml() {
    return dReplaceEmoji(this.get("title"));
  }

  @computed("draft_username")
  get editableDraft() {
    return this.draft_username === this.currentUser?.get("username");
  }

  @computed("username_lower")
  get userUrl(): string {
    return userPath(this.username_lower);
  }

  @computed("topic_id")
  get postUrl(): string | undefined {
    if (!this.topic_id) {
      return;
    }

    return postUrl(this.slug, this.topic_id, this.post_number);
  }

  @computed("draft_key")
  get draftType(): string | false {
    if (this.draft_key.startsWith(NEW_TOPIC_KEY)) {
      return i18n("drafts.new_topic");
    } else if (this.draft_key.startsWith(NEW_PRIVATE_MESSAGE_KEY)) {
      return i18n("drafts.new_private_message");
    } else if (this.draft_key.startsWith(EDIT_TOPIC_KEY)) {
      return i18n("drafts.edit_topic");
    }
    return false;
  }
}
import { computed } from "@ember/object";
import type { TrustedHTML } from "@ember/template";
import { Promise } from "rsvp";
import { ajax } from "discourse/lib/ajax";
import { cook, excerpt } from "discourse/lib/text";
import Category from "discourse/models/category";
import {
  NEW_PRIVATE_MESSAGE_KEY,
  NEW_TOPIC_KEY,
} from "discourse/models/composer";
import RestModel from "discourse/models/rest";
import Site from "discourse/models/site";
import type User from "discourse/models/user";
import UserDraft, {
  type UserDraftData,
  type UserDraftFields,
} from "discourse/models/user-draft";

export default class UserDraftsStream extends RestModel {
  declare user?: User;

  limit = 30;
  loading = false;
  hasMore = false;

  content: UserDraft[] | null = null;

  override init(...args: Parameters<RestModel["init"]>) {
    super.init(...args);
    this.reset();
  }

  @computed("content.length", "loading")
  get noContent() {
    return this.content?.length === 0 && !this.loading;
  }

  reset() {
    this.setProperties({
      loading: false,
      hasMore: true,
      content: [],
    });
  }

  remove(draft: UserDraft) {
    this.set(
      "content",
      this.content!.filter((item) => item.draft_key !== draft.draft_key)
    );
  }

  findItems(site?: Site) {
    if (site) {
      this.set("site", site);
    }

    if (this.loading || !this.hasMore) {
      return Promise.resolve<void>();
    }

    this.set("loading", true);

    const url = `/drafts.json?offset=${this.content!.length}&limit=${this.limit}`;
    return ajax(url)
      .then(
        (
          result:
            | {
                drafts?: (Omit<UserDraftFields, "data" | "post_number"> & {
                  data: string;
                  post_number?: number | null;
                })[];
                categories?: Parameters<Site["updateCategory"]>[0][];
              }
            | null
            | undefined
        ) => {
          if (!result) {
            return;
          }

          if (!result.drafts) {
            return;
          }

          result.categories?.forEach((category) =>
            Site.current().updateCategory(category)
          );

          // The endpoint returns an array without size; preserve its undefined numeric comparison.
          this.set(
            "hasMore",
            (result.drafts as typeof result.drafts & { size?: number }).size! >=
              this.limit
          );

          // Each wire object is mutated in place: parse data first, then hydrate its derived fields.
          const promises = (result.drafts as unknown as UserDraftFields[]).map(
            (draft) => {
              draft.data = JSON.parse(
                draft.data as unknown as string
              ) as UserDraftData;
              // TODO(typescript-pending): cook's dynamic engine return is untyped; remove the annotation when cook publishes its HTML result.
              return cook(draft.data.reply).then((cooked: TrustedHTML) => {
                draft.excerpt = excerpt(cooked.toString(), 300);
                draft.post_number = draft.data.postId || null;
                if (
                  draft.draft_key.startsWith(NEW_PRIVATE_MESSAGE_KEY) ||
                  draft.draft_key.startsWith(NEW_TOPIC_KEY)
                ) {
                  draft.title = draft.data.title;
                }
                if (draft.data.categoryId) {
                  draft.category =
                    Category.findById(draft.data.categoryId) || null;
                }

                this.content!.push(
                  UserDraft.create(
                    draft as UserDraftFields & Record<string, unknown>
                  )
                );
              });
            }
          );

          return Promise.all(promises);
        }
      )
      .finally(() => {
        this.set("loading", false);
      });
  }
}
import { tracked } from "@glimmer/tracking";
import EmberObject, { computed } from "@ember/object";
import { ajax } from "discourse/lib/ajax";
import getURL from "discourse/lib/get-url";
import { autoTrackedArray } from "discourse/lib/tracked-tools";
import type User from "discourse/models/user";
import UserAction, {
  type UserActionFields,
} from "discourse/models/user-action";

export interface UserPostsStreamFields {
  user?: User;
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type, @typescript-eslint/no-unsafe-declaration-merging
export default interface UserPostsStream extends UserPostsStreamFields {}

// eslint-disable-next-line @typescript-eslint/no-unsafe-declaration-merging
export default class UserPostsStream extends EmberObject {
  @tracked canLoadMore = true;
  @tracked filter: "deleted" | "pending" | undefined;
  @tracked itemsLoaded = 0;
  @tracked lastLoadedUrl: string | null | undefined;
  @tracked loaded = false;
  @tracked loading = false;
  @autoTrackedArray content: UserAction[] = [];

  @computed("user.username_lower", "filter", "itemsLoaded")
  get url(): string {
    return getURL(
      `/posts/${this.user?.username_lower}/${this.filter}?offset=${this.itemsLoaded}`
    );
  }

  async filterBy(opts: { filter: "deleted" | "pending" }): Promise<void> {
    if (this.loaded && this.filter === opts.filter) {
      return;
    }

    this.setProperties({
      itemsLoaded: 0,
      content: [],
      lastLoadedUrl: null,
      ...opts,
    });

    return this.findItems();
  }

  async findItems(): Promise<void> {
    if (this.loading || !this.canLoadMore) {
      return;
    }

    this.loading = true;

    try {
      const result = await ajax<
        (UserActionFields & Record<string, unknown>)[] | null | undefined
      >(this.url);
      if (result) {
        const posts = result.map((post) => UserAction.create(post));
        this.content.push(...posts);
        this.setProperties({
          loaded: true,
          itemsLoaded: this.itemsLoaded + posts.length,
          canLoadMore: posts.length > 0,
        });
      }
    } finally {
      this.loading = false;
    }
  }
}
import { tracked } from "@glimmer/tracking";
import { computed } from "@ember/object";
import { ajax } from "discourse/lib/ajax";
import { removeValueFromArray } from "discourse/lib/array-tools";
import getURL from "discourse/lib/get-url";
import { autoTrackedArray } from "discourse/lib/tracked-tools";
import type { CategoryFields } from "discourse/models/category";
import RestModel from "discourse/models/rest";
import Site from "discourse/models/site";
import type User from "discourse/models/user";
import UserAction, {
  type UserActionFields,
} from "discourse/models/user-action";

export interface UserStreamFilter {
  filter?: number | null;
  actingUsername?: string | null;
}

export interface UserStreamFields {
  user?: User;
  filter?: number | null;
}

// eslint-disable-next-line @typescript-eslint/no-empty-object-type, @typescript-eslint/no-unsafe-declaration-merging
export default interface UserStream extends UserStreamFields {}

// eslint-disable-next-line @typescript-eslint/no-unsafe-declaration-merging
export default class UserStream extends RestModel {
  @tracked actingUsername: string | null | undefined;
  @tracked lastLoadedUrl: string | null | undefined;
  @tracked loaded = false;
  @tracked loading = false;
  @tracked itemsLoaded = 0;
  @autoTrackedArray content: UserAction[] = [];

  @computed("itemsLoaded", "user.username_lower")
  get baseUrl(): string {
    return getURL(
      `/user_actions.json?offset=${this.itemsLoaded}&username=${this.user?.username_lower}`
    );
  }

  @computed("filter")
  get filterParam() {
    if (this.filter === UserAction.TYPES.replies) {
      return [UserAction.TYPES.replies, UserAction.TYPES.quotes].join(",");
    }

    if (!this.filter) {
      return [UserAction.TYPES.topics, UserAction.TYPES.posts].join(",");
    }

    return this.filter;
  }

  @computed("baseUrl", "filterParam", "actingUsername")
  get nextFindUrl(): string {
    let findUrl = this.baseUrl;
    if (this.filterParam) {
      findUrl += `&filter=${this.filterParam}`;
    }

    if (this.actingUsername) {
      findUrl += `&acting_username=${this.actingUsername}`;
    }

    return findUrl;
  }

  @computed("loaded", "content.[]")
  get noContent() {
    return this.loaded && this.content?.length === 0;
  }

  @computed("nextFindUrl", "lastLoadedUrl")
  get canLoadMore() {
    return this.nextFindUrl !== this.lastLoadedUrl;
  }

  async filterBy(opts: UserStreamFilter): Promise<void> {
    this.setProperties({
      itemsLoaded: 0,
      content: [],
      lastLoadedUrl: null,
      ...opts,
    });

    return this.findItems();
  }

  remove(userAction: UserAction): void {
    // 1) remove the user action from the child groups
    this.content.forEach((ua) => {
      ["likes", "stars", "edits", "bookmarks"].forEach((group) => {
        const items = ua.get(`childGroups.${group}.items`) as
          | UserAction[]
          | undefined;
        if (items) {
          removeValueFromArray(items, userAction);
        }
      });
    });

    // 2) remove the parents that have no children
    const content = this.content.filter((ua) => {
      return ["likes", "stars", "edits", "bookmarks"].some((group) => {
        // Missing child groups compare as undefined > 0, which excludes them.
        return (ua.get(`childGroups.${group}.items.length`) as number) > 0;
      });
    });

    this.setProperties({ content, itemsLoaded: content.length });
  }

  async findItems(): Promise<void> {
    if (this.loading || !this.canLoadMore) {
      // Don't load the same stream twice. We're probably at the end.
      return;
    }

    const findUrl = this.nextFindUrl;

    this.loading = true;
    try {
      const result = await ajax<
        | {
            user_actions?: (UserActionFields & Record<string, unknown>)[];
            categories?: CategoryFields[];
          }
        | null
        | undefined
      >(findUrl);
      if (result && result.user_actions) {
        const copy: UserAction[] = [];

        result.categories?.forEach((category) => {
          Site.current().updateCategory(category);
        });

        result.user_actions?.forEach((action) => {
          copy.push(UserAction.create(action));
        });

        this.content.push(...UserAction.collapseStream(copy));
        this.setProperties({
          itemsLoaded: this.itemsLoaded + result.user_actions.length,
        });
      }
    } finally {
      this.setProperties({
        loaded: true,
        loading: false,
        lastLoadedUrl: findUrl,
      });
    }
  }
}
