export type AjaxErrorXHR = JQuery.jqXHR & {
  jqTextStatus?: JQuery.Ajax.ErrorTextStatus;
  requestedUrl?: string;
};

/** What an `ajax` promise rejects with. */
export interface AjaxError {
  jqXHR: AjaxErrorXHR;
  textStatus: JQuery.Ajax.ErrorTextStatus;
  errorThrown: string;
